/**
 * North America: Canada and the United States.
 *
 * Every record was checked on 21 October 2026 against the organisation's own
 * pages (each URL in `links` fetched and read) and a second source: the CRA
 * charities listing (apps.cra-arc.gc.ca, business number in `registry`), the
 * IRS exempt-organisation record as ProPublica's Nonprofit Explorer shows it
 * (EIN in `registry`), or a network's own member list (the Waterkeeper
 * Alliance's member service behind waterkeeper.org/findyourwaterkeeper, the
 * BirdLife partner list). Public bodies carry `kind: "agency"` and no registry.
 *
 * Groups: Canada national, then by province west to east; the United States
 * national, then by state. `waters` are spelled as the fishing pages spell
 * them ("Lake Ontario", "Menomonee River").
 */
import type { Organisation, ServiceArea } from "./types";
import SHORE from "@/data/great-lakes-shore.json";

/**
 * The Great Lakes shore as areas: one corridor per lake ring (Natural Earth's shoreline, src/data/great-lakes-shore.json;
 * islands left out), each `km` wide, on the two ecoregions the lakes' shore towns fall in. A lake-wide body's area: the
 * Day 5 audit (14 November 2026) found boxes round the lakes that took in all of lower Michigan (Grand Rapids). An
 * ecoregion area reads "Covers your region", the right tier for a body that works lake-wide.
 */
const GREAT_LAKES_SHORE = (km: number): ServiceArea[] =>
  (SHORE as unknown as { rings: { name: string; island?: boolean; pts: [number, number][] }[] }).rings
    .filter((r) => !r.island)
    .map((r) => ({ kind: "ecoregion", ecoregions: ["great-lakes-st-lawrence", "boreal-forest"], corridor: { km, line: r.pts } }));

const V = "2026-10-21";
const CRA = (id: string) => ({ body: "CRA", id, url: `https://apps.cra-arc.gc.ca/ebci/hacc/srch/pub/dsplyQckVw/${id}/0` });
const IRS = (ein: string) => ({ body: "IRS", id: ein, url: `https://projects.propublica.org/nonprofits/organizations/${ein.replace("-", "")}` });
const WATERKEEPER_LIST = "https://services5.arcgis.com/hEkStteCvWjRBrR0/arcgis/rest/services/WaterkeeperWebsite_Boundaries/FeatureServer/0";
const BIRDLIFE_LIST = "https://en.wikipedia.org/wiki/List_of_BirdLife_International_national_partner_organisations";

/** A National Audubon Society state or regional programme: the office that runs the sanctuaries, centres and volunteer days in those states and points to the local chapters. */
const audubonRegion = (o: {
  slug: string;
  name: string;
  path: string;
  states: string[];
  blurb: string;
  asks: string[];
  localAsks?: Organisation["localAsks"];
  volunteer?: string;
  places?: string[];
  placeSources?: Record<string, string>;
  waters?: string[];
  verified?: string;
  sources?: string[];
}): Organisation => ({
  slug: o.slug,
  name: o.name,
  network: "National Audubon Society",
  scope: "regional",
  continent: "north-america",
  countryCode: "US",
  topics: ["birds", "plants", "youth"],
  areas: [{ kind: "admin1", countryCode: "US", admin1Codes: o.states }],
  waters: o.waters,
  blurb: o.blurb,
  asks: o.asks,
  ...(o.localAsks ? { localAsks: o.localAsks } : {}),
  links: {
    home: `https://www.audubon.org/${o.path}`,
    volunteer: o.volunteer ?? `https://www.audubon.org/${o.path}/get-involved`,
    events: "https://www.audubon.org/events",
    join: "https://www.audubon.org/about/audubon-near-you",
    donate: "https://www.audubon.org/ways-to-give",
    youth: "https://www.audubon.org/activities/audubon-adventures",
  },
  registry: IRS("13-1624102"),
  kind: "programme",
  places: o.places,
  ...(o.placeSources ? { placeSources: o.placeSources } : {}),
  verified: o.verified ?? V,
  sources: [`https://www.audubon.org/${o.path}`, ...(o.sources ?? []), "https://www.audubon.org/about/audubon-near-you", "https://projects.propublica.org/nonprofits/organizations/131624102"],
});

